/* * @lc app=leetcode id=3474 lang=kotlin * * [3474] Lexicographically Smallest Generated String */ class Solution { fun generateString(S: String, t: String): String = (S.length + t.length - 1).let { n -> CharArray(n) { '?' }.let { ans -> BooleanArray(n).let { isWild -> booleanArrayOf(true).let { ok -> S.indices.forEach { i -> if (S[i] == 'T') (0 until t.length).forEach { j -> if (ans[i + j] != '?' && ans[i + j] != t[j]) ok[0] = false else ans[i + j] = t[j] } }.let { ans.indices.forEach { i -> if (ans[i] == '?') ans[i] = 'a'.also { isWild[i] = true } } }.let { S.indices.forEach { i -> if (S[i] == 'F' && (0 until t.length).all { j -> ans[i + j] == t[j] }) (t.length - 1 downTo 0).firstOrNull { j -> isWild[i + j] }?.let { j -> ans[i + j] = 'b' } ?: run { ok[0] = false } } }.let { if (ok[0] && S.indices.all { i -> (S[i] == 'T') == (0 until t.length).all { j -> ans[i + j] == t[j] } }) String(ans) else "" } } } } } }